  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// ------------------------------------------------------\n// 1. USUARIOS Y SEGURIDAD (Control de Acceso Jerárquico)\n// ------------------------------------------------------\nenum Role {\n  ADMINISTRADOR\n  VENDEDOR\n  CONTADOR\n  BODEGUERO\n  CLIENTE\n}\n\nmodel User {\n  id             Int       @id @default(autoincrement())\n  email          String    @unique\n  password       String\n  role           Role      @default(VENDEDOR)\n  name           String\n  failedAttempts Int       @default(0)\n  lockUntil      DateTime?\n  lastLogin      DateTime?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  // Relaciones\n  sales          Sale[]\n  purchases      Purchase[]\n  kardexEntries  Kardex[]\n  journalEntries JournalEntry[]\n\n  @@index([email])\n}\n\n// ------------------------------------------------------\n// 2. PRODUCTOS E INVENTARIO (Con Borrado Seguro y Búsqueda Rápida)\n// ------------------------------------------------------\nmodel Product {\n  id          Int       @id @default(autoincrement())\n  barcode     String    @unique\n  name        String\n  category    String\n  brand       String?\n  description String?\n  unitMeasure String    @default(\"UNIDAD\") // Unidad, Caja, Metro, Kg\n  buyPrice    Float\n  sellPrice   Float\n  stock       Int       @default(0)\n  minStock    Int       @default(5)\n  deletedAt   DateTime? // Respaldo forense (Soft Delete para auditoría)\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  // Relaciones\n  kardex          Kardex[]\n  saleDetails     SaleDetail[]\n  purchaseDetails PurchaseDetail[]\n\n  @@index([barcode])\n  @@index([name])\n  @@index([category])\n}\n\n// ------------------------------------------------------\n// 3. KÁRDEX DE MOVIMIENTOS (Trazabilidad Contable e Inventario)\n// ------------------------------------------------------\nmodel Kardex {\n  id        Int      @id @default(autoincrement())\n  productId Int\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  type      String // 'ENTRADA', 'SALIDA', 'AJUSTE'\n  quantity  Int\n  reason    String? // Ej: \"Venta factura #001\", \"Compra proveedor\", \"Reposición\"\n  userId    Int?\n  user      User?    @relation(fields: [userId], references: [id])\n  createdAt DateTime @default(now())\n\n  @@index([productId])\n}\n\n// ------------------------------------------------------\n// 4. PROVEEDORES Y COMPRAS ENTRANTES\n// ------------------------------------------------------\nmodel Supplier {\n  id        Int      @id @default(autoincrement())\n  name      String\n  nit       String   @unique\n  phone     String?\n  address   String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  purchases Purchase[]\n}\n\nmodel Purchase {\n  id         Int      @id @default(autoincrement())\n  supplierId Int\n  supplier   Supplier @relation(fields: [supplierId], references: [id])\n  userId     Int\n  user       User     @relation(fields: [userId], references: [id])\n  total      Float\n  createdAt  DateTime @default(now())\n\n  details PurchaseDetail[]\n}\n\nmodel PurchaseDetail {\n  id         Int      @id @default(autoincrement())\n  purchaseId Int\n  purchase   Purchase @relation(fields: [purchaseId], references: [id], onDelete: Cascade)\n  productId  Int\n  product    Product  @relation(fields: [productId], references: [id])\n  quantity   Int\n  buyPrice   Float\n}\n\n// ------------------------------------------------------\n// 5. CLIENTES Y CARTERA (Gestión de Créditos y Abonos)\n// ------------------------------------------------------\nmodel Client {\n  id          Int       @id @default(autoincrement())\n  name        String\n  document    String    @unique // Cédula / NIT\n  phone       String?\n  address     String?\n  creditLimit Float     @default(0.0) // Cupo máximo de crédito\n  deletedAt   DateTime? // Soft Delete para auditorías\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  sales              Sale[]\n  accountsReceivable AccountReceivable[]\n}\n\nmodel AccountReceivable {\n  id          Int      @id @default(autoincrement())\n  clientId    Int\n  client      Client   @relation(fields: [clientId], references: [id])\n  saleId      Int      @unique\n  sale        Sale     @relation(fields: [saleId], references: [id])\n  totalAmount Float\n  balance     Float // Saldo pendiente por pagar\n  dueDate     DateTime // Alertas de vencimiento\n  status      String   @default(\"PENDIENTE\") // PENDIENTE, PAGADO, VENCIDO\n  createdAt   DateTime @default(now())\n\n  payments Payment[]\n}\n\nmodel Payment {\n  id                  Int               @id @default(autoincrement())\n  accountReceivableId Int\n  accountReceivable   AccountReceivable @relation(fields: [accountReceivableId], references: [id])\n  amount              Float\n  note                String?\n  createdAt           DateTime          @default(now())\n}\n\n// ------------------------------------------------------\n// 6. VENTAS Y PUNTO DE VENTA (POS)\n// ------------------------------------------------------\nmodel Sale {\n  id            Int      @id @default(autoincrement())\n  userId        Int\n  user          User     @relation(fields: [userId], references: [id])\n  clientId      Int?\n  client        Client?  @relation(fields: [clientId], references: [id])\n  paymentMethod String   @default(\"EFECTIVO\") // EFECTIVO, CREDITO, TRANSFERENCIA\n  total         Float\n  createdAt     DateTime @default(now())\n\n  details           SaleDetail[]\n  accountReceivable AccountReceivable?\n}\n\nmodel SaleDetail {\n  id        Int     @id @default(autoincrement())\n  saleId    Int\n  sale      Sale    @relation(fields: [saleId], references: [id], onDelete: Cascade)\n  productId Int\n  product   Product @relation(fields: [productId], references: [id])\n  quantity  Int\n  price     Float\n}\n\n// ------------------------------------------------------\n// 7. CONTABILIDAD INTEGRADA (NIIF para PYMES - PUC)\n// ------------------------------------------------------\nenum AccountType {\n  ACTIVO\n  PASIVO\n  PATRIMONIO\n  INGRESO\n  GASTO\n}\n\nmodel AccountPlan {\n  id           Int           @id @default(autoincrement())\n  code         String        @unique // Ej: \"1105\" (Caja), \"4135\" (Comercio)\n  name         String\n  type         AccountType\n  journalLines JournalLine[]\n}\n\nmodel JournalEntry {\n  id          Int           @id @default(autoincrement())\n  date        DateTime      @default(now())\n  description String // Ej: \"Registro automático venta POS #001\"\n  userId      Int\n  user        User          @relation(fields: [userId], references: [id])\n  lines       JournalLine[]\n  createdAt   DateTime      @default(now())\n}\n\nmodel JournalLine {\n  id             Int          @id @default(autoincrement())\n  journalEntryId Int\n  journalEntry   JournalEntry @relation(fields: [journalEntryId], references: [id], onDelete: Cascade)\n  accountId      Int\n  account        AccountPlan  @relation(fields: [accountId], references: [id])\n  debit          Float        @default(0.0)\n  credit         Float        @default(0.0)\n}\n",
